glsl3.vert:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
#if USE_LOCAL
  layout(std140) uniform CCLocal {
    highp mat4 cc_matWorld;
    highp mat4 cc_matWorldIT;
    highp vec4 cc_lightingMapUVParam;
    highp vec4 cc_localShadowBias;
    highp vec4 cc_reflectionProbeData1;
    highp vec4 cc_reflectionProbeData2;
    highp vec4 cc_reflectionProbeBlendData1;
    highp vec4 cc_reflectionProbeBlendData2;
  };
#endif
in vec3 a_position;
in vec2 a_texCoord;
in vec4 a_color;
out vec2 uv;
out vec4 tint;
vec4 vert () {
  vec4 p=vec4(a_position,1.);
  #if USE_LOCAL
    p=cc_matWorld*p;
  #endif
  uv=a_texCoord; tint=a_color;
  return cc_matViewProj*p;
}
void main() { gl_Position = vert(); }

glsl3.frag:
precision highp float;
vec4 CCSampleWithAlphaSeparated(sampler2D tex, vec2 uv) {
#if CC_USE_EMBEDDED_ALPHA
  return vec4(texture(tex, uv).rgb, texture(tex, uv + vec2(0.0, 0.5)).r);
#else
  return texture(tex, uv);
#endif
}
uniform sampler2D cc_spriteTexture;
uniform sampler2D reliefMap;
layout(std140) uniform FittingLight { vec4 pose; vec4 cardRect; };
in vec2 uv;
in vec4 tint;
float softbox(vec2 p, vec2 axis, float width, float extent) {
  vec2 d=vec2(dot(p,axis)/width,dot(p,vec2(-axis.y,axis.x))/extent);
  return exp(-dot(d,d));
}
vec4 frag () {
  vec4 base=CCSampleWithAlphaSeparated(cc_spriteTexture,uv);
  if(base.a<.002)return vec4(0.);
  vec4 relief=texture(reliefMap,uv);
  vec2 slope=relief.rg*2.-1.;
  vec3 normal=normalize(vec3(slope,sqrt(max(.045,1.-dot(slope,slope)))));
  vec2 pos=(cardRect.xy+uv*cardRect.zw-.5)*vec2(1.,-1.4167);
  vec3 eye=normalize(vec3(-.83*pose.x,-.62*pose.y,1.));
  if(pose.w>.5){
    vec3 frontLight=normalize(vec3(-.52,.66,.94));
    vec3 light=normalize(frontLight+vec3(-.68*pose.x,-.56*pose.y,0.));
    vec3 frontalHalf=normalize(frontLight+vec3(0.,0.,1.));
    vec3 halfDir=normalize(light+eye);
    float exponent=mix(10.,29.,relief.b);
    float glint=pow(max(0.,dot(normal,halfDir)),exponent)
               -pow(max(0.,dot(normal,frontalHalf)),exponent);
    float reliefLight=dot(normal,light)-dot(normal,frontLight);
    float bevel=smoothstep(.06,.58,length(slope));
    vec3 metalColor=mix(base.rgb,vec3(1.),.22);
    vec3 change=base.rgb*.28*reliefLight+metalColor*(.10+.30*bevel)*glint;
    return vec4(base.rgb+relief.a*change,base.a)*tint;
  }
  vec3 ray=reflect(-eye,normal);
  vec2 room=ray.xy/max(.52,ray.z)-pos*.28;
  float enamel=1.-smoothstep(.35,.48,relief.b);
  float metal=1.-enamel;
  vec2 axis=vec2(.885,.465);
  vec2 key=room-vec2(-.32,.44);
  float broad=softbox(key,axis,.39+enamel*.12,1.05);
  float strip=softbox(key+vec2(.055,.025),axis,.074+.052*enamel,.78);
  float rim=softbox(room-vec2(.49,-.21),vec2(.94,-.342),.13,.76);
  float fresnel=pow(1.-max(0.,dot(normal,eye)),2.);
  vec3 alloy=pose.z>2.5?vec3(.99,.87,.94):pose.z>1.5?vec3(.79,.91,1.):
             pose.z>.5?vec3(.79,.99,.88):vec3(1.,.79,.52);
  float polish=pose.z<.5?.60:pose.z<1.5?.76:1.;
  vec3 glazed=base.rgb*(.97+.08*broad)+vec3(.93,.97,1.)*(.055*broad+.29*strip+.09*rim);
  vec3 chased=base.rgb*(.87+.22*broad+.08*rim)
             +alloy*polish*(.12*broad+.49*strip+.20*rim+.07*fresnel);
  vec3 lit=glazed*enamel+chased*metal;
  return vec4(mix(base.rgb,lit,relief.a),base.a)*tint;
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

